using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
partial class Shelf {
 class FoundGame {public string Path,Name,LaunchUri,Arguments,WorkingDirectory,InstallRoot,PlatformId;public bool Official;public List<string> AlternatePaths=new List<string>();public DateTime Added;}
 static Dictionary<string,string[]> entryProfiles;
 void ApplyEntryProfiles(List<FoundGame> games){if(entryProfiles==null){using(var stream=typeof(Shelf).Assembly.GetManifestResourceStream("entry-profiles.json"))using(var reader=new StreamReader(stream))entryProfiles=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<Dictionary<string,string[]>>(reader.ReadToEnd());}foreach(var game in games){if(game.InstallRoot==null)continue;string[] profile;if(!entryProfiles.TryGetValue(System.IO.Path.GetFileName(game.InstallRoot).ToLowerInvariant(),out profile)||profile.Length<6)continue;string exe=System.IO.Path.Combine(game.InstallRoot,profile[0]);if(!File.Exists(exe))continue;game.Path=exe;game.Arguments=profile[1];game.WorkingDirectory=string.IsNullOrWhiteSpace(profile[2])?System.IO.Path.GetDirectoryName(exe):System.IO.Path.Combine(game.InstallRoot,profile[2]);game.LaunchUri=string.IsNullOrWhiteSpace(profile[3])?null:profile[3];game.Name=profile[4];}}
 static string NormalizeScanRoot(string path){string full=System.IO.Path.GetFullPath(path);return string.Equals(full.TrimEnd('\\','/'),System.IO.Path.GetPathRoot(full).TrimEnd('\\','/'),StringComparison.OrdinalIgnoreCase)?System.IO.Path.GetPathRoot(full):full.TrimEnd('\\','/');}
 static string[] MinimalScanRoots(IEnumerable<string> paths){var roots=paths.Select(NormalizeScanRoot).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();return roots.Where(p=>!roots.Any(other=>!p.Equals(other,StringComparison.OrdinalIgnoreCase)&&p.StartsWith(other.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))).ToArray();}
 class LibrarySnapshot {public int Version=1;public string[] Roots;public bool Shortcuts;public List<FoundGame> Games;public Dictionary<string,DirectoryInventory> Directories;}
 string SnapshotPath(){return System.IO.Path.Combine(home,"library-cache.json");}
 void SaveLibrarySnapshot(){var snapshot=new LibrarySnapshot{Roots=LibraryFolders(),Shortcuts=options.ScanShortcuts,Directories=directoryInventory.Where(pair=>LibraryFolders().Any(root=>pair.Key.Equals(root,StringComparison.OrdinalIgnoreCase)||pair.Key.StartsWith(root.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))).ToDictionary(pair=>pair.Key,pair=>pair.Value,StringComparer.OrdinalIgnoreCase),Games=games.Select(g=>new FoundGame{Path=g.Path,Name=g.OriginalName,LaunchUri=g.LaunchUri,Arguments=g.Arguments,WorkingDirectory=g.WorkingDirectory,Added=g.Added}).ToList()};string path=SnapshotPath();File.WriteAllText(path+".tmp",json.Serialize(snapshot));if(File.Exists(path))File.Replace(path+".tmp",path,path+".bak");else File.Move(path+".tmp",path);}
 bool RestoreLibrarySnapshot(){foreach(string path in new[]{SnapshotPath(),SnapshotPath()+".bak"})try{if(!File.Exists(path))continue;var snapshot=json.Deserialize<LibrarySnapshot>(File.ReadAllText(path));if(snapshot==null||snapshot.Version!=1||snapshot.Roots==null||snapshot.Games==null||snapshot.Shortcuts!=options.ScanShortcuts)continue;string[] roots=LibraryFolders();if(snapshot.Directories!=null)directoryInventory=new Dictionary<string,DirectoryInventory>(snapshot.Directories,StringComparer.OrdinalIgnoreCase);games=snapshot.Games.Where(g=>!string.IsNullOrWhiteSpace(g.Path)&&snapshot.Roots.Any(r=>roots.Contains(r,StringComparer.OrdinalIgnoreCase)&&g.Path.StartsWith(r.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))).GroupBy(g=>g.Path,StringComparer.OrdinalIgnoreCase).Select(group=>{var g=group.First();string cover=System.IO.Path.Combine(home,"covers",Hash(g.Path)+".jpg");return new Game{Path=g.Path,OriginalName=g.Name,Name=DisplayName(g.Name,cover),Cover=cover,LaunchUri=g.LaunchUri,Arguments=g.Arguments,WorkingDirectory=g.WorkingDirectory,Added=g.Added};}).ToList();Render();status.Text="已载入上次游戏库 · 后台检查目录变化";return true;}catch{}return false;}
 string[] LibraryFolders(){return (options.Folders!=null?options.Folders:new List<string>{folder}).Where(p=>!string.IsNullOrWhiteSpace(p)).Select(NormalizeScanRoot).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
 string LibraryKey(){return string.Join("|",LibraryFolders());}
 List<FoundGame> DiscoverLibraries(string[] roots){reusedDirectories=refreshedDirectories=0;var all=new Dictionary<string,FoundGame>(StringComparer.OrdinalIgnoreCase);foreach(string root in MinimalScanRoots(roots))if(Directory.Exists(root))foreach(var g in DiscoverGames(root,options.ScanShortcuts))all[g.Path]=g;return DedupeGames(all.Values).OrderBy(g=>g.Path,StringComparer.OrdinalIgnoreCase).ToList();}
 void OpenFolders(){NewModal("folders","游戏扫描目录","启动时扫描一次 · 点击顶部扫描按钮或 F5 可更新",520);foreach(string path in LibraryFolders()){string p=path;ModalRow("folder",p,Directory.Exists(p)?"包含子目录 · 点击查看或移除":"目录暂不可用",()=>OpenFolderActions(p));}ModalRow("plus","添加扫描目录","可添加磁盘或游戏文件夹",AddLibraryFolder);}
 void AddLibraryFolder(){using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="添加游戏安装目录或磁盘",ShowNewFolderButton=false})if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK){var roots=LibraryFolders().ToList();string path=System.IO.Path.GetFullPath(d.SelectedPath);if(!roots.Contains(path,StringComparer.OrdinalIgnoreCase))roots.Add(path);options.Folders=roots;folder=roots.Count>0?roots[0]:"";ResetDiscovery();OpenFolders();}}
 void OpenFolderActions(string path){NewModal("folder-actions","扫描目录",path,500);ModalRow("folder","在资源管理器中打开","查看这个目录",()=>{try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("explorer.exe","\""+path+"\""){UseShellExecute=true});}catch(Exception ex){status.Text=ex.Message;}});ModalRow("hide","移除此扫描目录","只从扫描列表移除，保留所有游戏文件",()=>{options.Folders=LibraryFolders().Where(p=>!p.Equals(path,StringComparison.OrdinalIgnoreCase)).ToList();folder=options.Folders.Count>0?options.Folders[0]:"";ResetDiscovery();OpenFolders();});}
 void ResetDiscovery(){signature="";nextDeepScan=DateTime.MinValue;Save();Scan();}
 string EffectiveEntry(Game g){string entry;return options.EntryOverrides!=null&&options.EntryOverrides.TryGetValue(g.Path,out entry)&&File.Exists(entry)?entry:g.Path;}
 void ChooseGameEntry(Game g){var dialog=new Microsoft.Win32.OpenFileDialog{Title="选择游戏启动程序",Filter="游戏程序|*.exe",InitialDirectory=System.IO.Path.GetDirectoryName(EffectiveEntry(g))};if(dialog.ShowDialog()!=true)return;if(options.EntryOverrides==null)options.EntryOverrides=new Dictionary<string,string>();options.EntryOverrides[g.Path]=dialog.FileName;Save();CloseModal();status.Text="已保存游戏启动入口 · "+g.Name;}
 void EpicMetadata(List<FoundGame> games,string root){string manifests=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"Epic","EpicGamesLauncher","Data","Manifests");foreach(string file in SafeFiles(manifests).Where(p=>p.EndsWith(".item",StringComparison.OrdinalIgnoreCase)))try{var data=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(file));if(!data.ContainsKey("InstallLocation")||!data.ContainsKey("LaunchExecutable")||string.IsNullOrWhiteSpace(Convert.ToString(data["LaunchExecutable"]))||(data.ContainsKey("bIsIncompleteInstall")&&Convert.ToBoolean(data["bIsIncompleteInstall"])))continue;string install=NormalizeScanRoot(Convert.ToString(data["InstallLocation"]));if(!install.Equals(root,StringComparison.OrdinalIgnoreCase)&&!install.StartsWith(root.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))continue;string exe=System.IO.Path.Combine(install,Convert.ToString(data["LaunchExecutable"]));if(!File.Exists(exe))continue;string app=Convert.ToString(data["AppName"]);var game=new FoundGame{Path=exe,Name=Convert.ToString(data["DisplayName"]),InstallRoot=install,Added=File.GetCreationTimeUtc(exe),Official=true,PlatformId="epic:"+app,LaunchUri="com.epicgames.launcher://apps/"+Uri.EscapeDataString(app)+"?action=launch&silent=true"};games.RemoveAll(g=>g.Path.StartsWith(install+"\\",StringComparison.OrdinalIgnoreCase));games.Add(game);}catch{}}
 static string DuplicateIdentity(FoundGame g){return MatchGameName(g.Name)+"|"+System.IO.Path.GetFileName(g.Path).ToLowerInvariant();}
 static List<FoundGame> DedupeGames(IEnumerable<FoundGame> games){var result=new List<FoundGame>();foreach(var group in games.GroupBy(DuplicateIdentity,StringComparer.OrdinalIgnoreCase)){var keep=group.OrderByDescending(g=>g.Official).ThenBy(g=>g.Path,StringComparer.OrdinalIgnoreCase).First();keep.AlternatePaths=group.Select(g=>g.Path).Where(p=>!p.Equals(keep.Path,StringComparison.OrdinalIgnoreCase)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();result.Add(keep);}return result;}
 void MergeDuplicateState(FoundGame game){string key=Hash(game.Path),cover=System.IO.Path.Combine(home,"covers",key+".jpg");foreach(string other in game.AlternatePaths){string sourceKey=Hash(other),source=System.IO.Path.Combine(home,"covers",sourceKey+".jpg");if(!HasCover(cover)&&HasCover(source)){foreach(string side in new[]{"",".title",".appid",".manual",".fit",".source"})if(File.Exists(source+side)&&!File.Exists(cover+side))File.Copy(source+side,cover+side,false);File.Delete(cover+".retry");}GameState state;if(options.Games.TryGetValue(sourceKey,out state)){GameState target;if(!options.Games.TryGetValue(key,out target))options.Games[key]=target=new GameState();target.Favorite|=state.Favorite;target.LastPlayed=Math.Max(target.LastPlayed,state.LastPlayed);target.PlayCount=Math.Max(target.PlayCount,state.PlayCount);}string entry;if(options.EntryOverrides.TryGetValue(other,out entry)&&!options.EntryOverrides.ContainsKey(game.Path))options.EntryOverrides[game.Path]=entry;}}
 bool scanning=false;DateTime nextDeepScan=DateTime.MinValue;
 static string MatchGameName(string name){name=System.Text.RegularExpressions.Regex.Replace(name,@"\bIII\b","3",System.Text.RegularExpressions.RegexOptions.IgnoreCase);name=System.Text.RegularExpressions.Regex.Replace(name,@"\bII\b","2",System.Text.RegularExpressions.RegexOptions.IgnoreCase);return Norm(name);}
 static string InstalledName(string name,string exe){string key=MatchGameName(name.Replace('_',' '));if(key.StartsWith("bloodborne"))return "血源诅咒";if(key=="fistgame")return "暗影火炬城";if(key.StartsWith("tw3goty"))return "巫师3：狂猎";if(key.StartsWith("nfs18rivals"))return "极品飞车18：宿敌";if(System.IO.Path.GetFileName(exe).StartsWith("pvzHE",StringComparison.OrdinalIgnoreCase))return "植物大战僵尸杂交版";var match=aliases.Where(a=>{string n=MatchGameName(a.Value);return n.Length>=5&&key.StartsWith(n);}).OrderByDescending(a=>MatchGameName(a.Value).Length).FirstOrDefault();return match.Key??System.Text.RegularExpressions.Regex.Replace(name,@"(?i)(?:[ ._-](?:v\d|build\d|early[ .]access|insaneramzes|chs[ .]|steam-rip)).*$","").Replace('_',' ').Trim();}
 static readonly HashSet<string> ScanSkip=new HashSet<string>(new[]{"$recycle.bin","system volume information","windows","programdata","node_modules",".git","_commonredist","_redist","dependencies","crack","cracks","backup","backups","wallpaper_engine","redist","redistributables","directx","vcredist","__installer","support","logs","cache","shadercache","content","assets","data","movies","videos","textures","localization","paks","dlss","dlss3","dllssd"},StringComparer.OrdinalIgnoreCase);
 static bool UtilityExe(string p){string n=System.IO.Path.GetFileNameWithoutExtension(p).ToLowerInvariant();if(n=="games"||n=="games.core")return true;return new[]{"卸载","修改器","dx_repair","crs-handler","crs-uploader","trainer","quicksvf","quicksfv","createdump","probe","ndp4","eosbootstrapper","unins","uninstall","setup","install","crashreport","crashhandler","report","prereq","vc_redist","vcredist","dxsetup","dotnet","unitycrash","cef","helper","service","updater","benchmark","config","server","editor","easyanticheat","battleye"}.Any(x=>n.Contains(x));}
 class DirectoryInventory {public long Stamp;public string[] Files,Children;}
 Dictionary<string,DirectoryInventory> directoryInventory=new Dictionary<string,DirectoryInventory>(StringComparer.OrdinalIgnoreCase);
 int reusedDirectories,refreshedDirectories;
 DirectoryInventory Inventory(string directory){long stamp=Directory.GetLastWriteTimeUtc(directory).Ticks;DirectoryInventory cached;if(directoryInventory.TryGetValue(directory,out cached)&&cached.Stamp==stamp&&cached.Files!=null&&cached.Children!=null&&cached.Files.All(File.Exists)&&cached.Children.All(Directory.Exists)){reusedDirectories++;return cached;}refreshedDirectories++;var entry=new DirectoryInventory{Stamp=stamp,Files=SafeFiles(directory).Where(p=>new[]{".exe",".lnk",".url"}.Contains(System.IO.Path.GetExtension(p).ToLowerInvariant())).ToArray(),Children=SafeDirectories(directory)};directoryInventory[directory]=entry;return entry;}
 static string[] SafeFiles(string d){try{return Directory.GetFiles(d);}catch{return new string[0];}}
 static string[] SafeDirectories(string d){try{return Directory.GetDirectories(d).Where(p=>!System.IO.Path.GetFileName(p).StartsWith("dependency_shared",StringComparison.OrdinalIgnoreCase)&&!ScanSkip.Contains(System.IO.Path.GetFileName(p))&&!System.IO.Path.GetFileName(p).ToLowerInvariant().Contains("backup")&&(File.GetAttributes(p)&(FileAttributes.ReparsePoint|FileAttributes.System))==0).ToArray();}catch{return new string[0];}}
 static bool ContainerDirectory(string p){return new[]{"games","game","游戏","steamlibrary","steamapps","common","epic games","epicgames","wegame","common_apps","epicyouxi","wegameapps"}.Contains(System.IO.Path.GetFileName(p).ToLowerInvariant());}
 static int ExeScore(string p,string install){string n=System.IO.Path.GetFileNameWithoutExtension(p).ToLowerInvariant();int score=0;if(n.Contains("shipping"))score+=60;if(n.Contains("win64"))score+=20;if(n.Contains("scimitar_engine"))score-=100;if(n.Contains("launcher"))score-=25;if(n.Contains("启动"))score+=80;if(System.IO.Path.GetDirectoryName(p)==install)score+=25;try{score+=(int)Math.Min(35,new FileInfo(p).Length/(1024*1024));}catch{}return score;}
 List<FoundGame> DiscoverGames(string root,bool shortcuts=false){root=NormalizeScanRoot(root);var links=new List<FoundGame>();var installs=new Dictionary<string,List<string>>(StringComparer.OrdinalIgnoreCase);var stack=new Stack<Tuple<string,int,string>>();stack.Push(Tuple.Create(root,0,!root.Equals(System.IO.Path.GetPathRoot(root),StringComparison.OrdinalIgnoreCase)&&!ContainerDirectory(root)&&Inventory(root).Files.Any(p=>p.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)&&!UtilityExe(p))?root:(string)null));
  while(stack.Count>0){var item=stack.Pop();string dir=item.Item1,bucket=item.Item3;int depth=item.Item2;var inventory=Inventory(dir);var files=inventory.Files;foreach(var p in files){string ext=System.IO.Path.GetExtension(p).ToLowerInvariant();if(shortcuts&&(ext==".lnk"||ext==".url"))links.Add(new FoundGame{Path=p,Name=System.IO.Path.GetFileNameWithoutExtension(p),Added=File.GetCreationTimeUtc(p)});else if(ext==".exe"&&!UtilityExe(p)){string key=bucket??dir;List<string> list;if(!installs.TryGetValue(key,out list))installs[key]=list=new List<string>();list.Add(p);}}
   if(depth>=6)continue;foreach(string child in inventory.Children){string next=bucket;if(next==null&&!ContainerDirectory(child))next=child;stack.Push(Tuple.Create(child,depth+1,next));}}
  var targets=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var link in links){try{var target=ResolveLaunch(new Game{Path=link.Path,Name=link.Name,OriginalName=link.Name},false);if(target.Exe!=null)targets.Add(System.IO.Path.GetFullPath(target.Exe));}catch{}}
  var result=new List<FoundGame>(links);foreach(var pair in installs){if(pair.Value.Any(p=>targets.Contains(p)))continue;string exe=pair.Value.OrderByDescending(p=>ExeScore(p,pair.Key)).ThenBy(p=>p,StringComparer.OrdinalIgnoreCase).First();string parent=System.IO.Path.GetFileName(pair.Key);string name=pair.Key.Equals(System.IO.Path.GetPathRoot(root),StringComparison.OrdinalIgnoreCase)?System.IO.Path.GetFileNameWithoutExtension(exe):parent;result.Add(new FoundGame{Path=exe,Name=name,InstallRoot=pair.Key,Added=File.GetCreationTimeUtc(exe)});}ApplyEntryProfiles(result);EpicMetadata(result,root);foreach(var game in result)game.Name=InstalledName(game.Name,game.Path);return result.OrderBy(p=>p.Path,StringComparer.OrdinalIgnoreCase).ToList();}
 async void Scan(){if(scanning)return;string requested=LibraryKey();string[] roots=LibraryFolders();if(!testMode&&DateTime.UtcNow<nextDeepScan)return;scanning=true;status.Text="正在扫描游戏安装目录…";try{var found=testMode?DiscoverLibraries(roots):await Task.Run(()=>DiscoverLibraries(roots));if(closing||LibraryKey()!=requested)return;var unavailable=roots.Where(p=>!Directory.Exists(p)).ToArray();foreach(var game in games)if(unavailable.Any(root=>game.Path.StartsWith(root.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase)))found.Add(new FoundGame{Path=game.Path,Name=game.OriginalName,LaunchUri=game.LaunchUri,Arguments=game.Arguments,WorkingDirectory=game.WorkingDirectory,Added=game.Added});found=found.GroupBy(g=>g.Path,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();string sig=requested+"#"+string.Join("|",found.Select(p=>p.Path+p.Added.Ticks+p.Arguments+p.WorkingDirectory+p.LaunchUri));if(sig==signature){if(!testMode)SaveLibrarySnapshot();status.Text=CacheSummary(games)+" · 扫描完成，无变化";return;}signature=sig;string keep=visible.Count>selected?visible[selected].Path:null;var old=games.ToDictionary(g=>g.Path,StringComparer.OrdinalIgnoreCase);games=found.Select(p=>{MergeDuplicateState(p);Game existing;if(old.TryGetValue(p.Path,out existing)){if(existing.OriginalName!=p.Name&&!HasCover(existing.Cover))File.Delete(existing.Cover+".retry");existing.OriginalName=p.Name;existing.Name=DisplayName(p.Name,existing.Cover);existing.LaunchUri=p.LaunchUri;existing.Arguments=p.Arguments;existing.WorkingDirectory=p.WorkingDirectory;return existing;}string cover=System.IO.Path.Combine(home,"covers",Hash(p.Path)+".jpg");return new Game{Path=p.Path,LaunchUri=p.LaunchUri,Arguments=p.Arguments,WorkingDirectory=p.WorkingDirectory,Name=DisplayName(p.Name,cover),OriginalName=p.Name,Cover=cover,Added=p.Added};}).ToList();if(!testMode){Save();SaveLibrarySnapshot();}Render(keep);if(unavailable.Length>0)status.Text="部分扫描目录暂不可用，已保留原有游戏";if(!testMode)UpdateCovers();}catch(Exception ex){status.Text="扫描失败 · "+ex.Message;}finally{scanning=false;nextDeepScan=DateTime.UtcNow.AddSeconds(15);if(LibraryKey()!=requested){nextDeepScan=DateTime.MinValue;Scan();}}}
}
